 function notice(text){toast.textContent=text;toast.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>toast.classList.remove('visible'),4500)}

 function button(label,glyph,fn,cls='nmc-icon-button'){const b=node('button',cls);b.type='button';b.setAttribute('aria-label',label);b.title=label;b.innerHTML=icon(glyph);b.onclick=task(fn);return b}

 function textButton(label,fn,cls='nmc-button'){const b=node('button',cls,label);b.type='button';b.onclick=task(fn);return b}

 function task(fn){return async e=>{const b=e?.currentTarget;if(b?.disabled)return;try{await fn(e)}catch(error){if(error.name!=='AbortError')notice(error.message||'Please try again.')}}}

 function setMusicCover(img,track){setRecentMusicCover(img,track)}
 function picture(track,cls=''){const img=node('img',cls);setMusicCover(img,track);img.alt='';img.loading='lazy';img.decoding='async';return img}

