 async function playList(tracks,at){tracks=tracks.map(refreshMusicAccess);const t=tracks[at];if(t?.playable===false){notice('This song needs SoundCloud’s own player or subscription access. Choose a song with public playback.');return}if(!isMusicTrack(t)){notice('This is from your previous music provider. Search for its SoundCloud version.');return}if(service.party){await service.partyAction('addSong',{song:t,requestId:crypto.randomUUID()});notice('Added to the party queue');return}queue=tracks.filter(t=>isMusicTrack(t)&&t.playable!==false);index=queue.findIndex(x=>x.id===t.id);const loading=load(t);paintQueue();await loading;paintQueue()}

