 function paintQueue(){const tracks=service.party?Object.values(service.party.queue||{}):queue,at=service.party?service.party.playback?.index||0:index;const upcoming=tracks[at+1]||(repeat===1?tracks[0]:null);if(upcoming)engine.prepare(upcoming);const sig=tracks.map(t=>t.id).join(',')+'|'+at+'|'+service.host;if(sig===lastRightQueue)return;lastRightQueue=sig;rightQueue.replaceChildren();tracks.slice(at+1,at+9).forEach((t,i)=>{const b=node('button','nmc-queue-entry');b.type='button';b.append(picture(t),node('span','',t.title));b.onclick=task(()=>service.party?hostControl('play',at+i+1):playList(queue,at+i+1));if(service.party&&!service.host)b.disabled=true;rightQueue.append(b)});if(!rightQueue.children.length)rightQueue.append(node('p','nmc-muted','Your next track will appear here.'))}

