 function paintRange(input){const min=Number(input.min)||0,max=Number(input.max)||0;const percent=max>min?Math.max(0,Math.min(100,(Number(input.value)-min)/(max-min)*100)):0;input.style.setProperty('--nmc-fill',percent+'%')}
